    const local = [feet[0] - t[0] - b.locOrigin[0], feet[1] - t[1] - b.locOrigin[1], feet[2] - t[2] - b.locOrigin[2]];
    const locId = `${dfLoc.regionIndex}:${dfLoc.name}`;
