    if (!_profileAsk) return;
    if (!_profileAsk.sent) _profileAsk.sent = online?.sendCard({ to: _profileAsk.peerId, ask: true }) === true;
    if (performance.now() - _profileAsk.at < CARD_WAIT_MS) return;
    const id = _profileAsk.peerId;
    _profileAsk = null;
